template.script:
(function () {
    window.setTimeout(function () {
        var wrap = document.getElementById("wrap");
        if (!wrap || wrap.querySelector(".ut-owl-mount-host")) {
            return;
        }
        var fallback = wrap.querySelector("[data-ut-seller-fallback='1']");
        if (fallback) {
            fallback.style.display = "block";
        }
    }, 8000);
})();

div.script:
(function () {
    window.setTimeout(function () {
        var wrap = document.getElementById("wrap");
